#main.main{display:grid;grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto minmax(0,1fr);min-width:0}
#main.main>#context.context{position:static;inset:auto;width:auto;height:auto;max-height:none;z-index:auto;box-shadow:none;grid-column:auto;grid-row:auto;min-width:0}
#screen.content,.reading,.article,.field select,.article pre,.table-wrap{min-width:0;max-width:100%}
.reading{max-width:min(700px,100%);overflow-x:auto}
.article pre,.table-wrap{overflow:auto}
@media(min-width:768px){
#main.main:has(>#context.context:not([hidden]))>.topbar{grid-column:1;grid-row:1;min-width:0}
#main.main:has(>#context.context:not([hidden]))>#banner{grid-column:1;grid-row:2;min-width:0}
#main.main:has(>#context.context:not([hidden]))>#screen.content{grid-column:1;grid-row:3;min-width:0}
#main.main:has(>#context.context:not([hidden]))>#context.context:not([hidden]){grid-column:2;grid-row:1/span 3;position:static;inset:auto;z-index:auto;box-shadow:none;width:auto;height:auto;max-height:none;min-width:0;align-self:stretch;overflow:hidden;border-left:1px solid var(--line)}
}
@media(min-width:1280px){
.app{grid-template-columns:var(--side-w) minmax(0,1fr)}
#main.main:has(>#context.context:not([hidden])){grid-template-columns:minmax(0,1fr) 340px}
}
@media(min-width:768px) and (max-width:1279px){
.app{grid-template-columns:minmax(0,1fr)}
.app>.sidebar{position:fixed;z-index:30;inset:0 auto 0 0;width:min(86vw,var(--side-w));height:100dvh;transform:translateX(-105%)}
.app.nav-open>.sidebar{transform:none;box-shadow:var(--shadow)}
[data-action="nav:toggle"],[data-action="nav:close"]{display:inline-flex !important}
#main.main>#screen.content{padding:20px}
#main.main:has(>#context.context:not([hidden])){grid-template-columns:minmax(0,1fr) clamp(320px,33.333vw,340px)}
}
@media(max-width:767px){
#main.main{grid-template-columns:minmax(0,1fr)}
#main.main>#context.context:not([hidden]){position:fixed;inset:0;width:100%;height:100dvh;max-height:100dvh;z-index:40;box-shadow:none;border-left:0;grid-column:1;grid-row:auto}
}

